        check_io(8'h36, 4'd6, 1'b1);
        // 8'h3d -> 7
        check_io(8'h3d, 4'd7, 1'b1);
        // 8'h3e -> 8
        check_io(8'h3e, 4'd8, 1'b1);
        // 8'h46 -> 9
        check_io(8'h46, 4'd9, 1'b1);

        // Test invalid scancodes / edge cases
        // 8'h00 -> invalid, outputs should be 0
        check_io(8'h00, 4'd0, 1'b0);
        // 8'hFF -> invalid, outputs should be 0
        check_io(8'hFF, 4'd0, 1'b0);
        // Near miss scancode (e.g., 8'h44) -> invalid
        check_io(8'h44, 4'd0, 1'b0);
        // Another near miss (8'h17) -> invalid
        check_io(8'h17, 4'd0, 1'b0);

        // Final Result Evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
